const examples={property:{title:'Every property enquiry.<br>A clear next step.',description:'A buyer asks about a listing. Their details reach your CRM, the right agent gets notified, and a follow-up task is created automatically.',outcome:'More conversations. Less chasing information.',steps:[['Enquiry received','Website or connected lead source'],['Agent assigned & notified','Details and property interest in one place'],['Follow-up scheduled','A clear next action in your CRM']]},services:{title:'Work approved.<br>Paperwork already moving.',description:'A project milestone is approved. An invoice draft is prepared from the agreed details, routed for review, and a payment reminder is scheduled after it is sent.',outcome:'Keep projects moving from delivery to payment.',steps:[['Milestone approved','Your team confirms the work is ready'],['Invoice draft prepared','Review details before anything is sent'],['Payment reminder scheduled','Follow up on outstanding invoices']]},trading:{title:'Stock running low?<br>Stay one step ahead.',description:'When stock reaches your chosen threshold, the purchasing team gets an alert and a reorder request is prepared for approval. A daily summary keeps everyone informed.',outcome:'Clear stock signals. Timely purchasing decisions.',steps:[['Low stock detected','Your chosen inventory threshold'],['Reorder request prepared','Purchasing manager reviews and approves'],['Daily summary delivered','Stock alerts and order status together']]}};
function showExample(key){const item=examples[key];document.getElementById('example-title').innerHTML=item.title;document.getElementById('example-description').textContent=item.description;document.getElementById('example-outcome').textContent=item.outcome;document.getElementById('example-steps').innerHTML=item.steps.map((s,i)=>`<div class="step"><span>0${i+1}</span><div><strong>${s[0]}</strong><small>${s[1]}</small></div></div>`).join('');document.getElementById('example-panel').setAttribute('aria-labelledby','tab-'+key);document.querySelectorAll('[role="tab"]').forEach(t=>{const active=t.dataset.example===key;t.setAttribute('aria-selected',active);t.tabIndex=active?0:-1})}const tabs=[...document.querySelectorAll('[role="tab"]')];tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>showExample(tab.dataset.example));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();tabs[n].focus();showExample(tabs[n].dataset.example)}})});showExample('property');const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
